-- หลักสูตร วท.บ. วิทยาการคอมพิวเตอร์ (ปรับปรุง พ.ศ. 2566) วิชาเอกคอมพิวเตอร์และวิทยาการสารสนเทศ
-- เฉพาะวิชา คพ. (CS) ที่เป็นวิชาบังคับ: ชื่อวิชา คำอธิบาย และวิชาบังคับก่อน มาจากเล่มหลักสูตร
-- หัวข้อในแต่ละวิชา (topics) แต่งเองจากคำอธิบายรายวิชา ยังไม่ใช่ของจริง แก้ได้ภายหลัง
--
-- วิธีรัน (หลัง backend เปิดครั้งแรกแล้ว เพราะ Hibernate เป็นคนสร้างตาราง):
--   set -a && . ./.env && set +a
--   docker exec -i -e MYSQL_PWD="$MYSQL_ROOT_PASSWORD" cs261-solo-mysql-1 mysql --default-character-set=utf8mb4 -uroot "$MYSQL_DATABASE" < db/curriculum-2566.sql
-- แล้วล้าง cache วิชาใน Redis ไม่อย่างนั้นหน้าเว็บยังเห็นข้อมูลเก่า:
--   docker exec cs261-solo-redis-1 sh -c 'for p in "skillTree::*" "courseDetails::*"; do redis-cli --scan --pattern "$p" | while read -r k; do redis-cli del "$k"; done; done'

-- Hibernate สร้างคอลัมน์ desc เป็น varchar(255) แต่คำอธิบายรายวิชาบางวิชายาวกว่านั้น → ขยายเป็น text
alter table courses modify `desc` text;

-- ===== ล้างข้อมูลหลักสูตรเดิมทั้งหมดก่อน (รวม progress ที่ผูกกับหัวข้อเดิม) =====
delete from progress;
delete from relation_topic_course;
delete from prerequisites;
delete from topics;
delete from courses;

