insert into courses (id, code, name, `desc`) values
  (UUID_TO_BIN('c0000000-0000-0000-0000-000000000100'), 'CS100', 'Basic Web Development', 'แนวคิดพื้นฐานในการพัฒนาเว็บ สถาปัตยกรรมเว็บ เอชทีเอ็มแอลและซีเอสเอสเบื้องต้น วงจรการพัฒนาด้วยกิท การโปรแกรมจาวาสคริปต์ ฟอร์มและการยืนยันความถูกต้อง ส่วนประกอบของเว็บที่สามารถตอบสนองได้ การนำเว็บขึ้นให้บริการ'),
  (UUID_TO_BIN('c0000000-0000-0000-0000-000000000101'), 'CS101', 'Discrete Structures', 'ตรรกศาสตร์เบื้องต้นและการประยุกต์ใช้ในวงจรดิจิทัลพื้นฐาน วิธีการพิสูจน์ เซต ฟังก์ชัน ความสัมพันธ์ พีชคณิตบูลีน พื้นฐานการนับ และกราฟ โดยเน้นการประยุกต์ใช้ในด้านวิทยาการคอมพิวเตอร์'),
  (UUID_TO_BIN('c0000000-0000-0000-0000-000000000102'), 'CS102', 'Problem Solving Basics and Computer Programming', 'การแก้ปัญหาด้วยวิธีการทางคอมพิวเตอร์ การออกแบบและการโปรแกรมเชิงโครงสร้าง ชนิดของข้อมูล โครงสร้างการควบคุม ฟังก์ชันและการส่งค่าพารามิเตอร์ ฟังก์ชันเวียนเกิด การทดสอบ และตรวจหาข้อผิดพลาด'),
  (UUID_TO_BIN('c0000000-0000-0000-0000-000000000111'), 'CS111', 'Object-Oriented Concepts', 'พัฒนาทักษะการวิเคราะห์และการแก้ปัญหาด้วยแนวคิดเชิงวัตถุ บูรณาการแนวคิดและแนวทางเชิงปฏิบัติที่ทันสมัยในวัฏจักรการพัฒนาซอฟต์แวร์ หลักการพื้นฐานในการเขียนโปรแกรมเชิงวัตถุตามที่วิเคราะห์และออกแบบไว้ แนวทางในการทวนสอบความสอดคล้องระหว่างแบบและซอร์สโค้ด'),
  (UUID_TO_BIN('c0000000-0000-0000-0000-000000000180'), 'CS180', 'Introduction to User Interface and User Experience', 'ความสำคัญของการออกแบบส่วนต่อประสานกับผู้ใช้และประสบการณ์ผู้ใช้ต่อการพัฒนาระบบที่ใช้งานได้ กระบวนการออกแบบที่เน้นผู้ใช้เป็นศูนย์กลาง เครื่องมือ การวัดและประเมินผล ส่วนประกอบการออกแบบส่วนต่อประสานกับผู้ใช้ ส่วนประกอบการออกแบบมาตรฐานและแนวปฏิบัติในการออกแบบเพื่อนำกลับมาใช้ใหม่ผ่านระบบการออกแบบที่มีอยู่ แนวทางส่วนต่อประสานผู้ใช้และประสบการณ์ผู้ใช้'),
  (UUID_TO_BIN('c0000000-0000-0000-0000-000000000213'), 'CS213', 'Data Structures', 'การวิเคราะห์ขั้นตอนวิธีเบื้องต้น หลักนามธรรมข้อมูล โครงสร้างข้อมูลพื้นฐาน ได้แก่ ข้อมูลเชิงเส้นและข้อมูลแบบไม่เชิงเส้น การจัดสรรหน่วยเก็บแบบพลวัต เทคนิคการค้นหา และการเรียงลำดับข้อมูลในหน่วยความจำ'),
  (UUID_TO_BIN('c0000000-0000-0000-0000-000000000217'), 'CS217', 'Design and Analysis of Algorithms', 'เทคนิคต่าง ๆ ที่ใช้ในการออกแบบและวิเคราะห์ขั้นตอนวิธี ได้แก่ วิธีการแบ่งแยกเอาชนะ วิธีละโมบ วิธีกำหนดการพลวัต วิธีการแวะผ่านบัพทุกบัพของกราฟ วิธีการย้อนรอย และวิธีบรานช์แอนด์บาวด์'),
  (UUID_TO_BIN('c0000000-0000-0000-0000-000000000221'), 'CS221', 'Introduction to Computer System and Organization', 'โครงสร้างและสถาปัตยกรรมคอมพิวเตอร์ การออกแบบหน่วยประมวลผลและระบบคอมพิวเตอร์ที่มีประสิทธิภาพ สมรรถนะของระบบคอมพิวเตอร์ ระบบแทนข้อมูลและการจัดการข้อมูลแบบครบหน่วย ลำดับชั้นของหน่วยความจำในระบบคอมพิวเตอร์ ไปป์ไลนิง การจัดลำดับงานแบบสถิตและแบบพลวัต การประมวลผลซูเปอร์สเกลาร์และเวกเตอร์ แคช สถาปัตยกรรมชุดคำสั่งเครื่อง มัลติโพรเซสเซอร์ และสถาปัตยกรรมทางเลือกอื่น'),
  (UUID_TO_BIN('c0000000-0000-0000-0000-000000000222'), 'CS222', 'Operating Systems', 'แนวคิดพื้นฐานการออกแบบและการสร้างระบบปฏิบัติการ องค์ประกอบและโครงสร้างของระบบปฏิบัติการ สภาพแวดล้อมแบบคอมมานด์ไลน์ การจัดการโปรเซส การจัดลำดับการประมวลผลของซีพียู การจัดการหน่วยความจำ การจัดการระบบไฟล์ การจัดการอุปกรณ์ ภาวะทำงานพร้อมกันและการประสานจังหวะ ความปลอดภัยระบบคอมพิวเตอร์ กรณีศึกษา'),
  (UUID_TO_BIN('c0000000-0000-0000-0000-000000000223'), 'CS223', 'Virtualization Technology', 'แนวคิดพื้นฐานเกี่ยวกับการจำลองสภาพแวดล้อมเสมือน การจำลองสภาพแวดล้อมเสมือนแบบไฮเปอร์ไวเซอร์ เทคโนโลยีเครื่องเสมือน การจำลองสภาพแวดล้อมเสมือนแบบคอนเทนเนอร์ เทคโนโลยีคอนเทนเนอร์ เครือข่ายเสมือน การจัดการและประสานการทำงาน'),
  (UUID_TO_BIN('c0000000-0000-0000-0000-000000000232'), 'CS232', 'Introduction to Cloud Computing Technology', 'คุณลักษณะของการประมวลผลแบบกลุ่มเมฆ รูปแบบการให้บริการของการประมวลผลแบบกลุ่มเมฆ เช่น ไอเอเอเอส พีเอเอเอส และเอสเอเอเอส ทักษะการพัฒนาแอปพลิเคชันเพื่อให้บริการผ่านเทคโนโลยีกลุ่มเมฆ การรักษาความปลอดภัยบนกลุ่มเมฆ'),
  (UUID_TO_BIN('c0000000-0000-0000-0000-000000000240'), 'CS240', 'Principles of Data Science', 'หลักการพื้นฐานของวิทยาการข้อมูลที่เกี่ยวข้องกับอัลกอริทึม กระบวนการ วิธีการ และหลักการคิด รวมทั้งเครื่องมือที่ใช้ในการวิเคราะห์ข้อมูล หัวข้อพื้นฐานในวิทยาการข้อมูล ได้แก่ การจัดการข้อมูล การวิเคราะห์ข้อมูลเชิงสถิติและเชิงการเรียนรู้ของเครื่องจักร การนำเสนอข้อมูลด้วยทัศนสารสนเทศ และการทำงานกับข้อมูลขนาดใหญ่'),
  (UUID_TO_BIN('c0000000-0000-0000-0000-000000000241'), 'CS241', 'Programming Languages and Paradigms', 'หลักการของภาษาโปรแกรม ไวยากรณ์และวากยสัมพันธ์ ศึกษากรอบแนวคิดของภาษาโปรแกรมประเภทต่าง ๆ การโปรแกรมโดยคำนึงถึงสมรรถนะ การโปรแกรมโดยอาศัยส่วนต่อประสานโปรแกรมประยุกต์ ไลบรารีสำหรับจัดการข้อมูล และการโปรแกรมเชิงเหตุการณ์'),
  (UUID_TO_BIN('c0000000-0000-0000-0000-000000000242'), 'CS242', 'Python Programming and Applications', 'ทักษะการเขียนโปรแกรม การแก้ปัญหา และการคิดเชิงอัลกอริทึมด้วยภาษาไพทอน หัวข้อรวมถึงตัวแปร อินพุต/เอาต์พุต คำสั่งเงื่อนไข นิพจน์บูลีน โครงสร้างการควบคุม ฟังก์ชัน และประเภทข้อมูลบิวต์อินในภาษา ศึกษาการสร้างแอปพลิเคชันด้วยภาษาไพทอนและไลบรารียอดนิยมในสาขาวิทยาการข้อมูล หรือเครือข่าย หรือการพัฒนาเว็บ มีการฝึกปฏิบัติผ่านการทำโครงงาน'),
  (UUID_TO_BIN('c0000000-0000-0000-0000-000000000251'), 'CS251', 'Database Systems 1', 'แนวคิดพื้นฐานและสถาปัตยกรรมของระบบฐานข้อมูล การจำลองข้อมูลเชิงแนวคิด การออกแบบฐานข้อมูลและการทำให้เกิดผล ภาษาสอบถาม เมทาดาตา การจัดระเบียบแฟ้มและหน่วยเก็บข้อมูลเชิงกายภาพ แนะนำการจัดการรายการเปลี่ยนแปลง'),
  (UUID_TO_BIN('c0000000-0000-0000-0000-000000000261'), 'CS261', 'Introduction to Software Engineering', 'คุณลักษณะซอฟต์แวร์ คุณภาพของซอฟต์แวร์และโครงการซอฟต์แวร์ หลักการของวิศวกรรมซอฟต์แวร์ ระเบียบวิธีในการพัฒนาซอฟต์แวร์ กระบวนการพัฒนาซอฟต์แวร์ที่สำคัญ การวางแผนและจัดการโครงการ การประเมินเวลาและค่าใช้จ่าย วิเคราะห์และการระบุข้อกำหนด เทคนิคการวิเคราะห์และออกแบบซอฟต์แวร์ แนะนำสถาปัตยกรรมซอฟต์แวร์ เทคนิคการพัฒนาโปรแกรม การตรวจสอบและการทวนสอบซอฟต์แวร์ วิวัฒนาการของซอฟต์แวร์ สภาพแวดล้อมการผลิตซอฟต์แวร์และเครื่องมือช่วยจัดการโครงการ กรณีศึกษา'),
  (UUID_TO_BIN('c0000000-0000-0000-0000-000000000271'), 'CS271', 'Artificial Intelligence Fundamentals', 'ปัญหาทางปัญญาประดิษฐ์ การแทนความรู้ การค้นหาแบบไม่มีข้อมูล การค้นหาแบบมีข้อมูล ปัญหาการทำตามเงื่อนไข ตรรกศาสตร์และการให้เหตุผลอัตโนมัติ การค้นหาเชิงปฏิปักษ์ การเรียนรู้ของเครื่องจักรเบื้องต้น'),
  (UUID_TO_BIN('c0000000-0000-0000-0000-000000000301'), 'CS301', 'Preparation for Senior Projects and Co-operative Education', 'ฝึกทักษะที่จำเป็นต้องใช้ในการทำงานทั้งด้านวิชาการและภาคธุรกิจ การเขียนใบสมัครงาน การเขียนประวัติ การสัมภาษณ์ การคิดเชิงวิพากษ์ การสืบค้นข้อมูลเพื่อประกอบการทำงาน การทำงานเป็นทีมในการพัฒนาซอฟต์แวร์ การเขียนรายงานและการอ้างอิง การนำเสนอ รวมถึงเทคนิคการเจรจาสื่อสารภายในองค์กร'),
  (UUID_TO_BIN('c0000000-0000-0000-0000-000000000305'), 'CS305', 'Social and Professional Ethics', 'บริบททางสังคมของระบบคอมพิวเตอร์ วิธีการและเครื่องมือในการวิเคราะห์ ความรับผิดชอบและจรรยาบรรณทางวิชาชีพ กฎหมายทรัพย์สินทางปัญญา การยอมรับความเสี่ยงและการชดใช้ต่อระบบคอมพิวเตอร์ การละเมิดทรัพย์สินทางปัญญา การละเมิดสิทธิส่วนบุคคล อาชญากรรมในระบบคอมพิวเตอร์'),
  (UUID_TO_BIN('c0000000-0000-0000-0000-000000000314'), 'CS314', 'Automata Theory', 'มูลฐานของเครื่องจักรนามธรรมและภาษา ทฤษฎีออโตมาตา นิพจน์แบบเรกูลาร์ ภาษาแบบเรกูลาร์ ออโตมาตาแบบกดลง ภาษาไม่พึ่งบริบท เครื่องจักรทัวริง ปัญหาการหยุด ความสามารถและประสิทธิภาพในการแก้ปัญหาของเครื่องคอมพิวเตอร์'),
  (UUID_TO_BIN('c0000000-0000-0000-0000-000000000331'), 'CS331', 'Net-Centric Computing', 'องค์ประกอบหลักและมาตรฐานเครือข่ายสำหรับการโอนถ่ายข้อมูลผ่านระบบเครือข่ายอินเทอร์เน็ต แบบจำลองแบบลำดับชั้นโอเอสไอ แบบจำลองแบบลำดับชั้นทีซีพี/ไอพี หน้าที่หลักของแต่ละลำดับชั้น โปรโตคอลหลักในแต่ละลำดับชั้นและการทำงานร่วมกัน การเขียนโปรแกรมซ็อกเก็ต'),
  (UUID_TO_BIN('c0000000-0000-0000-0000-000000000332'), 'CS332', 'Computer System Security', 'ความปลอดภัยของระบบคอมพิวเตอร์เบื้องต้น ภัยคุกคามและช่องโหว่ การพิสูจน์ตัวตนและการควบคุมการเข้าถึง การเข้ารหัสและลายมือชื่อดิจิทัล ความปลอดภัยของโปรแกรมและโปรแกรมประสงค์ร้าย ความปลอดภัยของระบบปฏิบัติการ ระบบฐานข้อมูล การโจมตีเครือข่ายและการป้องกัน ความปลอดภัยของแอปพลิเคชันบนเครือข่าย ประเด็นด้านกฎหมายและความเป็นส่วนตัว'),
  (UUID_TO_BIN('c0000000-0000-0000-0000-000000000372'), 'CS372', 'Machine Learning', 'ทฤษฎีการเรียนรู้ การเรียนรู้เชิงอุปนัยและนิรนัย การเรียนรู้เบย์อย่างง่าย ต้นไม้ตัดสินใจ การเรียนรู้แบบมีผู้สอน การเรียนรู้แบบไม่มีผู้สอน การเรียนรู้แบบเสริมแรง ปัญหาการเข้ากันมากเกินไป การประเมินความถูกต้อง การประเมินประสิทธิภาพ และตัวอย่างการประยุกต์ใช้การเรียนรู้ของเครื่อง เช่น การทำเหมืองข้อมูล การควบคุมหุ่นยนต์ การนำทางแบบอัตโนมัติ และชีวสารสนเทศศาสตร์');
insert into prerequisites (id, course_id, prerequisite_id, timestamp) values
  (UUID_TO_BIN(UUID()), UUID_TO_BIN('c0000000-0000-0000-0000-000000000111'), UUID_TO_BIN('c0000000-0000-0000-0000-000000000102'), now()),  -- CS111 ต้องผ่าน CS102,
  (UUID_TO_BIN(UUID()), UUID_TO_BIN('c0000000-0000-0000-0000-000000000213'), UUID_TO_BIN('c0000000-0000-0000-0000-000000000111'), now()),  -- CS213 ต้องผ่าน CS111,
  (UUID_TO_BIN(UUID()), UUID_TO_BIN('c0000000-0000-0000-0000-000000000217'), UUID_TO_BIN('c0000000-0000-0000-0000-000000000213'), now()),  -- CS217 ต้องผ่าน CS213,
  (UUID_TO_BIN(UUID()), UUID_TO_BIN('c0000000-0000-0000-0000-000000000221'), UUID_TO_BIN('c0000000-0000-0000-0000-000000000101'), now()),  -- CS221 ต้องผ่าน CS101,
